summary:
bash: cat > /tmp/kt2.c <<'EOF'
#include <klee/klee.h>
int main(void) {
  int x;
  klee_make_symbolic(&x, sizeof(x), "x");
  if (x > 10) { if (x == 42) klee_assert(0); }
  return 0;
}
EOF
bash -c 'source ~/.bashrc; clang-16 -emit-llvm -c -g -O0 -Xclang -disable-O0-optnone /tmp/kt2.c -o /tmp/kt2.bc && rm -rf /tmp/klee-out-kt2 && klee --solver-backend=stp --output-dir=/tmp/klee-out-kt2 /tmp/kt2.bc 2>&1 | tail -20'

